import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int[] sizes = {nextInt(), nextInt(), nextInt()};
        long[][] arr = new long[3][];
        for (int t = 0; t < 3; t++) {
            arr[t] = new long[sizes[t]];
            for (int i = 0; i < sizes[t]; i++) arr[t][i] = nextLong();
        }
        int[] idx = new int[3];
        StringBuilder sb = new StringBuilder();
        boolean any = false;
        long lastValue = 0;
        while (true) {
            // Take the smallest unconsumed head among the three arrays.
            int src = -1;
            for (int t = 0; t < 3; t++)
                if (idx[t] < sizes[t] && (src < 0 || arr[t][idx[t]] < arr[src][idx[src]])) src = t;
            if (src < 0) break;
            long value = arr[src][idx[src]++];
            if (!any || value != lastValue) {
                if (any) sb.append(' ');
                sb.append(value);
                any = true;
                lastValue = value;
            }
        }
        sb.append('\n');
        System.out.print(sb);
    }
}

package main

import (
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func next() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	var sizes [3]int
	for t := range sizes {
		sizes[t] = int(nextInt())
	}
	var arr [3][]int64
	for t := 0; t < 3; t++ {
		arr[t] = make([]int64, sizes[t])
		for i := range arr[t] {
			arr[t][i] = nextInt()
		}
	}
	var idx [3]int
	out := []byte{}
	any := false
	var lastValue int64
	for {
		// Take the smallest unconsumed head among the three arrays.
		src := -1
		for t := 0; t < 3; t++ {
			if idx[t] < sizes[t] && (src < 0 || arr[t][idx[t]] < arr[src][idx[src]]) {
				src = t
			}
		}
		if src < 0 {
			break
		}
		value := arr[src][idx[src]]
		idx[src]++
		if !any || value != lastValue {
			if any {
				out = append(out, ' ')
			}
			out = strconv.AppendInt(out, value, 10)
			any = true
			lastValue = value
		}
	}
	out = append(out, '\n')
	os.Stdout.Write(out)
}
